#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#include "atomic.h"
#include "lr_algo.h"

// Generated by train_surrogate_lr_fidelity.py (copied in by run_surrogate_lr.py):
//   lr_weights_header/w_Trace_dev_{0,1}_lr.h
// Each defines LR_DEV_<d>_N_FEATURES, double lr_weight_dev_<d>[] and double lr_bias_dev_<d>.
#include "lr_weights_header/w_Trace_dev_0_lr.h"
#include "lr_weights_header/w_Trace_dev_1_lr.h"

#if LR_DEV_0_N_FEATURES != LEN_INPUT || LR_DEV_1_N_FEATURES != LEN_INPUT
#error "Logistic regression header feature count does not match LEN_INPUT"
#endif

// Same history pool as the FlashNet and decision-tree replayers
// (non-static: inference_latency/bench.c reaches them via extern).
long queue_len;
long hist_index;
long *prev_queue_len;
long *prev_latency;
long *prev_throughput;

static const double *lr_weight_all[DEVICE_NUM] = {
    lr_weight_dev_0,
    lr_weight_dev_1,
};

static const double *lr_bias_all[DEVICE_NUM] = {
    &lr_bias_dev_0,
    &lr_bias_dev_1,
};

long add_fetch_cur_queue_len() {
    return atomic_inc_fetch(&queue_len);
}

void inc_queue_len() {
    atomic_inc(&queue_len);
}

void dec_queue_len() {
    atomic_dec(&queue_len);
}

void set_surrogate_lr(int total_io_num) {
    queue_len = 0;
    hist_index = 0;

    prev_queue_len = malloc(total_io_num * sizeof(long));
    prev_latency = malloc(total_io_num * sizeof(long));
    prev_throughput = malloc(total_io_num * sizeof(long));
    if (!prev_queue_len || !prev_latency || !prev_throughput) {
        printf("[Error] memory allocation failed in set_surrogate_lr\n");
        exit(1);
    }
    for (long i = 0; i < total_io_num; i++) {
        prev_queue_len[i] = -1;
        prev_latency[i] = -1;
        prev_throughput[i] = -1;
    }
}

int surrogate_lr_inference(long io_type, long size, uint32_t device, long cur_queue_len) {
    // 1. Build the feature vector exactly like surrogate_dt_inference() does
    //    (zeros for history slots that are not filled yet).
    long input_vec_i[LEN_INPUT] = {0};
    input_vec_i[0] = io_type;
    input_vec_i[1] = size;
    input_vec_i[2] = cur_queue_len;

    long cur_hist_index = hist_index;
    for (int i = 1; i <= N_HIST; i++) {
        if (cur_hist_index - i >= 0) {
            input_vec_i[2 + i] = prev_queue_len[cur_hist_index - i];
            input_vec_i[5 + i] = prev_latency[cur_hist_index - i];
            input_vec_i[8 + i] = prev_throughput[cur_hist_index - i];
        }
    }

    if (device >= DEVICE_NUM) {
        printf("[Error] device index %u out of range\n", device);
        exit(1);
    }

    // 2. Linear decision function. The scaler is already folded into the weights.
    //    Accumulation order (bias first, then feature 0..11) is mirrored by the
    //    trainer's header_match_rate check.
    const double *w = lr_weight_all[device];
    double acc = *lr_bias_all[device];
    for (int j = 0; j < LEN_INPUT; j++) {
        acc += w[j] * (double)input_vec_i[j];
    }

    int pred = (acc > 0.0) ? 1 : 0;   // sigmoid(acc) > 0.5  <=>  acc > 0
    if (VERBOSE) {
        printf("[dev %u] - [cur_hist_index=%ld] z=%.6f pred=%d\n", device, cur_hist_index, acc, pred);
    }
    return pred;
}

void update_surrogate_lr(long io_queue_len, long io_latency, long io_throughput) {
    prev_queue_len[hist_index] = io_queue_len;
    prev_latency[hist_index] = io_latency;
    prev_throughput[hist_index] = io_throughput;
    hist_index += 1;
}

void free_surrogate_lr() {
    free(prev_queue_len);
    free(prev_latency);
    free(prev_throughput);
}
